/* SF-080: measured population history; unknown past ticks remain gaps. */
function populationHistoryKey(colony){return JSON.stringify([colony.centralPlayerId||colony.accountId||'local',colony.centralResetGeneration??null,colony.resetEpoch||0,colony.planetType||'']);}
function initializePopulationHistory(colony,foundingPopulation=colony?.population){if(!colony||!Number.isSafeInteger(foundingPopulation)||foundingPopulation<0)return;colony.populationHistory={version:1,key:populationHistoryKey(colony),points:[[0,foundingPopulation]],baseline:'creation',lastTick:0,truncated:false};}
function recordPopulationHistory(colony){
 if(!colony||!Number.isSafeInteger(colony.tick)||colony.tick<0||!Number.isSafeInteger(colony.population)||colony.population<0)return null;
 const key=populationHistoryKey(colony);let history=colony.populationHistory;
 if(!history||history.version!==1||history.key!==key||!Array.isArray(history.points)||history.lastTick>colony.tick){history={version:1,key,points:[],baseline:null,lastTick:colony.tick,truncated:false};const own=colony.galaxy?.find(p=>p.player);if(own&&Number.isSafeInteger(own.foundingPopulation)&&own.foundingPopulation>=0&&(own.resetEpoch||0)===(colony.resetEpoch||0)){history.points=[[0,own.foundingPopulation]];history.baseline='creation';}}
 // Reject imported/corrupt measurements rather than inventing replacements.
 const valid=new Map();for(const point of history.points.slice(-10000)){if(Array.isArray(point)&&Number.isSafeInteger(point[0])&&point[0]>=0&&point[0]<=colony.tick&&Number.isSafeInteger(point[1])&&point[1]>=0)valid.set(point[0],point[1]);}
 valid.set(colony.tick,colony.population);history.points=[...valid].sort((a,b)=>a[0]-b[0]);if(history.points.length>10000){history.points=history.points.slice(-10000);history.truncated=true;}history.lastTick=colony.tick;colony.populationHistory=history;return history;
}
function populationHistoryHTML(colony){
 const history=recordPopulationHistory(colony);if(!history)return '';
 const points=history.points,maxTick=Math.max(1,colony.tick),values=points.map(p=>p[1]),minimum=Math.min(...values),maximum=Math.max(...values),spread=Math.max(1,maximum-minimum),low=Math.max(0,minimum-spread*.1),high=maximum+spread*.1;
 const x=t=>54+((t/maxTick)*610),y=p=>148-((p-low)/(high-low))*112,fmt=n=>Math.floor(n).toLocaleString('en-US');
 let path='',previous=null;for(const point of points){path+=(previous&&point[0]===previous[0]+1?' L':' M')+x(point[0]).toFixed(2)+' '+y(point[1]).toFixed(2);previous=point;}
 const first=points[0],last=points[points.length-1],unknown=first[0]>0||points.some((p,i)=>i&&p[0]>points[i-1][0]+1),note=(history.baseline==='creation'&&first[0]===0?'Tick 0 records the population at colony creation. ':'Earlier population was not recorded. ')+(unknown?'Missing ticks are gaps; no growth has been estimated. ':'Every displayed tick is a recorded observation. ')+(history.truncated?'Only the latest 10,000 observations are retained. ':'')+'History is saved with this colony on this browser.';
 return '<section class="population-history" aria-label="Population history" style="margin:10px 12px;padding:10px;border:1px solid currentColor;border-radius:5px;color:inherit"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>POPULATION PROGRESS</b><small>TICK 0–'+colony.tick+' · '+fmt(colony.population)+' RESIDENTS</small></div><svg viewBox="0 0 700 180" role="img" aria-label="Population measurements from tick '+first[0]+' to '+last[0]+'. Current population '+fmt(last[1])+'.'+(unknown?' Some ticks have no observations.':'')+'" style="display:block;width:100%;max-height:190px;color:inherit"><title>Population progress · tick 0 to '+colony.tick+'</title><desc>'+note+'</desc><path d="M54 24 V148 H664" fill="none" stroke="currentColor" opacity=".45"/><path d="M54 92 H664 M54 36 H664" fill="none" stroke="currentColor" opacity=".12"/><text x="48" y="39" text-anchor="end" fill="currentColor" font-size="10">'+fmt(high)+'</text><text x="48" y="151" text-anchor="end" fill="currentColor" font-size="10">'+fmt(low)+'</text><text x="54" y="169" fill="currentColor" font-size="11">Tick 0</text><text x="664" y="169" text-anchor="end" fill="currentColor" font-size="11">Tick '+colony.tick+'</text><path d="'+path+'" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke"/>'+points.filter((p,i)=>i===0||i===points.length-1||(!points[i-1]||p[0]!==points[i-1][0]+1)||(!points[i+1]||points[i+1][0]!==p[0]+1)).map(p=>'<circle cx="'+x(p[0]).toFixed(2)+'" cy="'+y(p[1]).toFixed(2)+'" r="3" fill="currentColor"><title>Tick '+p[0]+': '+fmt(p[1])+' residents</title></circle>').join('')+'</svg><p class="meta" style="margin:4px 0;line-height:1.5">'+note+'</p><details><summary>Recorded measurements ('+points.length+')</summary><div style="max-height:180px;overflow:auto"><table class="table"><caption>Measured residents by tick</caption><thead><tr><th scope="col">Tick</th><th scope="col">Residents</th></tr></thead><tbody>'+points.map(p=>'<tr><th scope="row">'+p[0]+'</th><td>'+fmt(p[1])+'</td></tr>').join('')+'</tbody></table></div></details></section>';
}
